fn on_load(env: rustler::Env, _info: rustler::Term) -> bool {
    env.register::<DefaultClient>()
        .expect("Failed to register resource type DefaultClient");
    env.register::<SingleflightResult>()
        .expect("Failed to register resource type SingleflightResult");
    env.register::<DefaultClientChatStreamHandle>()
        .expect("Failed to register resource type DefaultClientChatStreamHandle");
    true
}

rustler::init!("Elixir.LiterLlm.Native", load = on_load);
